package com.franco.desco.adapter.in.web.catalog;import io.swagger.v3.oas.annotations.media.Schema;import jakarta.validation.constraints.*;
public final class CatalogRequests{private CatalogRequests(){} @Schema(name="CatalogCreateRequest") public record Create(@NotBlank @Size(max=40) String catalogo,@NotBlank @Size(max=40) String codigo,@NotBlank @Size(max=150) String nombre,@Size(max=300) String descripcion,@Size(max=20) String categoria){} @Schema(name="CatalogUpdateRequest") public record Update(@NotBlank @Size(max=40) String catalogo,@NotBlank @Size(max=150) String nombre,@Size(max=300) String descripcion,@Size(max=20) String categoria){} @Schema(name="CatalogDisableRequest") public record Disable(@NotBlank @Size(max=40) String catalogo,@NotBlank @Size(max=300) String motivo){} }
